'use client';

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import type { ResourceLocator } from '@hachej/boring-files';
import { createResourceClient } from '@hachej/boring-files/remote';
import type { ResourceIdentity } from '@hachej/boring-files/remote';
import type { NativeChatController } from '@hachej/boring-ui-kit/native-chat';
import { PiChat, artifactKey } from '../pi-chat/pi-chat';
import type { ArtifactDescriptor, ArtifactsConfig, ConversationsConfig, PiChatProps } from '../pi-chat/pi-chat';
import { ArtifactWorkspace } from '../pi-workspace/workspace';
import type { WorkspacePanelApi } from '../pi-workspace/workspace';
import { ViewerWindowProvider } from '../viewers/viewer-frame';
import type { ViewerShare } from '../viewers/viewer-frame';
import type { InteractiveHtml } from '../viewers/interactive-html';
import { Button } from '../button/button';
import type { BlockAction } from '../button/actions';
import { ChatTextProvider, useMergedText } from '../pi-chat/labels';
import { cn, withDefaults } from '../utils/utils';
import { AppTextProvider, defaultAppIcons, defaultAppLabels } from './app-labels';
import type { AppIcons, AppLabels } from './app-labels';
import { ArtifactPanel, useArtifactVersions, useTurn } from './artifact-panel';
import type { CustomViewers, SavedRevision, ViewerOptions } from './artifact-panel';
import { FileViewer } from './file-viewer';
import { SessionsPane, SessionsToggle } from './sessions';

export { ArtifactPanel, useArtifactVersions, useTurn } from './artifact-panel';
export type { CustomViewerProps, CustomViewers, SavedRevision, ViewerOptions } from './artifact-panel';
export { FileViewer } from './file-viewer';
export { SessionsPane, SessionsToggle } from './sessions';
export { useConversations } from './use-conversations';
export { useRemoteChat } from './use-remote-chat';
export type { RemoteChatState } from './use-remote-chat';
export { savedLabel, useSaved } from './use-saved';
export { kindOf, mediaTypeOf } from './file-kinds';
export { defaultAppIcons, defaultAppLabels } from './app-labels';
export type { AppIcons, AppLabels } from './app-labels';
export type { FileKind } from './file-kinds';

/** An artifact version in the panel: `follow` shows the latest saved revision, otherwise `descriptor.revision` is pinned and read-only. */
export interface ArtifactView { readonly kind: 'artifact'; readonly conversation: string; readonly descriptor: ArtifactDescriptor; readonly follow: boolean }
/** A file in the panel, by the host's path (see `resources.locate`). */
export interface FileView { readonly kind: 'file'; readonly path: string }
/** Anything else the host renders in the panel through `panels[kind]` (for example a file list or a tool view). */
export interface HostView { readonly kind: string; readonly [field: string]: unknown }
/** What the right-hand panel shows, or `null` when it is closed. */
export type OpenedView = ArtifactView | FileView | HostView;

const isArtifact = (view: OpenedView | null): view is ArtifactView => view?.kind === 'artifact';
const isFile = (view: OpenedView | null): view is FileView => view?.kind === 'file';

/** Where the viewers read and write: the host's resource handler (`createResourceHandler` of `@hachej/boring-files/remote`) and its file history. */
export interface WorkspaceResources {
  /** The resource handler endpoint. */
  readonly endpoint: string | URL;
  /** The host's authenticated fetch, also used for `history`. */
  readonly fetch: (request: Request) => Promise<Response>;
  /** The person's identity as the resource handler authenticates it (comparison metadata, never a grant). */
  readonly identity: ResourceIdentity;
  /** Optional `GET <history>?path=<resource path>` returning `{ saves: [{ revision, savedAt }] }` newest first (`files.saves(path)`): the version menu. */
  readonly history?: string | URL | undefined;
  /** The resource of a file path in a `FileView`. Default: the published `workspace` provider at the path without a leading slash. */
  readonly locate?: ((path: string) => ResourceLocator) | undefined;
}

export interface AgentWorkspaceProps {
  /** The open conversation's controller (`useRemoteChat`); `undefined` while connecting, when `connecting` is shown instead. */
  readonly controller: NativeChatController | undefined;
  /** The open conversation: auto-opened artifacts and the artifact view belong to it. */
  readonly conversationId: string | undefined;
  /** Everything else `PiChat` takes (labels, icons, headerActions, messageActions, mode, actions, slash, mentions, attachments, model, effort, emptyState, ...). */
  readonly chat?: Omit<PiChatProps, 'controller' | 'artifacts' | 'conversations' | 'historyList'>;
  /**
   * The block's words (sessions pane, artifact panel, file viewer and the viewers' bars), over `defaultAppLabels`; for example
   * `{ sessionsTitle: 'Projects', newChat: 'Start' }`. The chat's own go in `chat.labels`.
   */
  readonly labels?: Partial<AppLabels> | undefined;
  /** The block's icons (sessions toggle, New, Float chat, the viewer bar's), over `defaultAppIcons`. The chat's go in `chat.icons`. */
  readonly icons?: Partial<AppIcons> | undefined;
  /**
   * Host actions on the artifact panel's bar (every viewer it shows), after the built-in Float chat: `header` ones as buttons beside Share,
   * `menu` ones in its "…" menu. A function receives what is open. Test ids `<viewer testId>-<id>` (`artifact-<id>` for an artifact).
   */
  readonly panelActions?: readonly BlockAction[] | ((view: OpenedView) => readonly BlockAction[]) | undefined;
  readonly connecting?: ReactNode;
  /** The sessions pane (`useConversations`). Omit it for a page without one. Replies keep their Fork button through `conversations.fork`. */
  readonly conversations?: ConversationsConfig | undefined;
  readonly resources: WorkspaceResources;
  /** Recognise artifacts in tool results that carry no descriptor (`ArtifactsConfig.detect`). */
  readonly detect?: ArtifactsConfig['detect'] | undefined;
  /** Host viewers by artifact type or file kind, for example `{ canvas: props => <MyCanvas {...props} /> }`. */
  readonly viewers?: CustomViewers | undefined;
  /** Run HTML pages in the viewers' sandboxed preview, loading scripts only from these origins. Off without it. */
  readonly interactive?: InteractiveHtml | undefined;
  /** The viewer bar's Share action; it receives `target` `{ artifact, version }` or `{ file }`. */
  readonly share?: ViewerShare | undefined;
  /** Controlled panel content (with `onOpenedChange`); uncontrolled from `defaultOpened` otherwise. */
  readonly opened?: OpenedView | null | undefined;
  readonly defaultOpened?: OpenedView | null | undefined;
  readonly onOpenedChange?: ((next: OpenedView | null) => void) | undefined;
  /** Renderers for host views, by `kind`. */
  readonly panels?: Readonly<Record<string, (view: HostView, panel: WorkspacePanelApi) => ReactNode>> | undefined;
  /** Open the panel on each artifact (or new version) the agent makes, unless the person closed it during this turn. Not on a phone. Default true. */
  readonly autoOpen?: boolean;
  /** A back button in a file's viewer bar (for example to the host's file list). */
  readonly fileBack?: { readonly label: string; readonly onBack: () => void } | undefined;
  /** With `floatBelow`: the floating chat over the same session (for example `AmbientChat` of `pi-ambient` with `onDock={dock}`). */
  readonly floatingChat?: ((props: PiChatProps, dock: () => void) => ReactNode) | undefined;
  /** Shown above the chat (notices). */
  readonly chatTop?: ReactNode;
  /** The chat header's controls; a function receives whether the panel is open. */
  readonly controls?: ReactNode | ((state: { readonly panelOpen: boolean }) => ReactNode);
  /** Prefix of the session-scoped layout keys (panel width, floating chat, collapsed sessions). */
  readonly storageKey?: string;
  /** Below this width of the workspace the artifact panel is a full-screen sheet. */
  readonly sheetBelow?: number;
  /** Below this width of the workspace the sessions pane is a drawer. */
  readonly drawerBelow?: number;
  readonly floatBelow?: number | undefined;
  readonly className?: string;
}

const SESSIONS_WIDTH = 288;
const readFlag = (key: string): boolean => { try { return sessionStorage.getItem(key) === '1'; } catch { return false; } };
const writeFlag = (key: string, on: boolean) => { try { if (on) sessionStorage.setItem(key, '1'); else sessionStorage.removeItem(key); } catch { /* the layout is a convenience */ } };
const defaultLocate = (path: string): ResourceLocator => ({ resource: { providerId: 'workspace', path: path.replace(/^\/+/, '') }, view: { kind: 'published' } });

/**
 * A complete agent page in one component: the sessions pane on the left (search, New, rename, archive, delete; collapsible, a drawer on
 * a narrow screen), the chat in the center (`PiChat`) and the artifact viewers on the right (`ArtifactWorkspace` with the artifact panel and
 * its versions, the file viewer and the host's own views). Agent artifacts open the panel as they appear. Every prop is data or a callback:
 * the host owns the routes, authentication, the controller and what is open (when controlled).
 */
export function AgentWorkspace({ controller, conversationId, chat = {}, labels, icons, panelActions, connecting, conversations, resources, detect, viewers, interactive, share, opened: controlled,
  defaultOpened = null, onOpenedChange, panels, autoOpen = true, fileBack, floatingChat, chatTop, controls, storageKey = 'boring.agent-workspace', sheetBelow = 768, drawerBelow = 768, floatBelow, className }: AgentWorkspaceProps) {
  const [own, setOwn] = useState<OpenedView | null>(defaultOpened);
  const opened = controlled !== undefined ? controlled : own;
  const change = useRef(onOpenedChange); change.current = onOpenedChange;
  const isControlled = controlled !== undefined;
  const setOpened = useCallback((next: OpenedView | null) => { if (!isControlled) setOwn(next); change.current?.(next); }, [isControlled]);
  const [fullscreen, setFullscreen] = useState(false);
  const text = useMemo(() => ({ labels: withDefaults(defaultAppLabels, labels), icons: withDefaults(defaultAppIcons, icons) }), [labels, icons]);
  // The sessions pane shows the chat's conversation list, so it reads the chat's labels too.
  const chatText = useMergedText(chat.labels, chat.icons);

  // One resource client and one history reader for every viewer, over the host's authenticated fetch.
  const fetcher = useRef(resources.fetch); fetcher.current = resources.fetch;
  const endpoint = String(resources.endpoint), historyEndpoint = resources.history === undefined ? undefined : String(resources.history);
  const identityKey = JSON.stringify(resources.identity);
  const client = useMemo(() => createResourceClient({ identity: resources.identity, endpoint: new URL(endpoint, globalThis.location?.href), publication: true, reconciliation: true,
    fetch: request => fetcher.current(request) }), [endpoint, identityKey]); // eslint-disable-line react-hooks/exhaustive-deps
  const history = useMemo(() => historyEndpoint === undefined ? undefined : async (path: string): Promise<readonly SavedRevision[]> => {
    const url = new URL(historyEndpoint, globalThis.location?.href);
    url.searchParams.set('path', path);
    const response = await fetcher.current(new Request(url));
    if (!response.ok) throw new Error(`History: ${response.status}`);
    return (await response.json() as { saves: readonly SavedRevision[] }).saves;
  }, [historyEndpoint]);
  const options: ViewerOptions = useMemo(() => ({ client, identity: resources.identity, history, viewers, interactive, share }), [client, history, viewers, interactive, share]); // eslint-disable-line react-hooks/exhaustive-deps
  const locate = resources.locate ?? defaultLocate;

  // ---- Artifacts: cards open the panel; the agent's new ones open it too.
  const versions = useArtifactVersions(controller, detect);
  const turn = useTurn(controller);
  const active = isArtifact(opened) && opened.conversation === conversationId ? opened : null;
  const file = isFile(opened) ? opened : null;
  const host = opened && !isArtifact(opened) && !isFile(opened) && panels?.[opened.kind] ? opened : null;
  const panelOpen = Boolean(active || file || host);
  const seen = useRef(new Map<string, Set<string>>());
  const closedInTurn = useRef(new Map<string, number>());
  const close = () => { if (conversationId !== undefined) closedInTurn.current.set(conversationId, turn); setOpened(null); setFullscreen(false); };
  useEffect(() => {
    if (!controller || conversationId === undefined) return;
    const keys = versions.map(version => `${artifactKey(version)}:${version.revision}`);
    const known = seen.current.get(conversationId);
    // What the conversation already held when it loaded does not count.
    if (!known) { seen.current.set(conversationId, new Set(keys)); return; }
    const fresh = versions.filter(version => !known.has(`${artifactKey(version)}:${version.revision}`));
    for (const key of keys) known.add(key);
    if (!autoOpen || !fresh.length || closedInTurn.current.get(conversationId) === turn || globalThis.matchMedia?.(`(max-width: ${sheetBelow - 1}px)`).matches) return;
    setOpened({ kind: 'artifact', conversation: conversationId, descriptor: fresh.at(-1)!, follow: true });
  }, [versions, controller, conversationId, turn]); // eslint-disable-line react-hooks/exhaustive-deps
  /** The versions of one file that the conversation presented or saved, newest first. */
  const newestOf = (key: string) => versions.filter(version => artifactKey(version) === key).reverse();
  const artifacts: ArtifactsConfig = useMemo(() => ({
    open: descriptor => { if (conversationId !== undefined) setOpened({ kind: 'artifact', conversation: conversationId, descriptor, follow: descriptor.revision === newestOf(artifactKey(descriptor))[0]?.revision }); },
    isOpen: descriptor => Boolean(active && artifactKey(active.descriptor) === artifactKey(descriptor) && (active.follow ? descriptor.revision === newestOf(artifactKey(descriptor))[0]?.revision : descriptor.revision === active.descriptor.revision)),
    ...(detect ? { detect } : {}),
  }), [conversationId, active, versions, detect, setOpened]); // eslint-disable-line react-hooks/exhaustive-deps

  // ---- Sessions: docked on a wide workspace (collapsible, remembered for the session), a drawer on a narrow one.
  const root = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);
  useLayoutEffect(() => {
    const element = root.current;
    if (!element) return;
    const measure = () => setWidth(element.getBoundingClientRect().width);
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  const narrow = width > 0 && width < drawerBelow;
  const [collapsed, setCollapsed] = useState(() => readFlag(`${storageKey}.sessions-hidden`));
  const [drawer, setDrawer] = useState(false);
  useEffect(() => { if (!narrow) setDrawer(false); }, [narrow]);
  const docked = Boolean(conversations) && width > 0 && !narrow && !collapsed;
  const toggle = conversations && <SessionsToggle open={narrow ? drawer : !collapsed} drawer={narrow}
    onToggle={() => { if (narrow) setDrawer(value => !value); else setCollapsed(value => { writeFlag(`${storageKey}.sessions-hidden`, !value); return !value; }); }} />;

  // ---- The docked chat's header is replaced on every switch and connect (the `connecting` row, then a new `PiChat`). The toggle is not
  // part of it: it stays mounted in the shell, over an invisible space of its size in whichever header is showing, and follows that
  // header's height. A press that starts before the swap ends on the same button and still clicks (a button that leaves the document
  // between press and release loses the click, even when moved rather than recreated).
  const toggleRow = useRef<HTMLDivElement>(null);
  const followHeader = useRef<ResizeObserver | undefined>(undefined);
  const headerSlot = useCallback((space: HTMLElement | null) => {
    followHeader.current?.disconnect(); followHeader.current = undefined;
    const header = space?.parentElement;
    if (!header || typeof ResizeObserver === 'undefined') return;
    followHeader.current = new ResizeObserver(() => { if (toggleRow.current) toggleRow.current.style.height = `${header.clientHeight}px`; });
    followHeader.current.observe(header);
  }, []);
  const toggleSpace = toggle && <Button ref={headerSlot} size="icon-sm" aria-hidden="true" tabIndex={-1} className="invisible -ml-1" />;

  // ---- The chat in the center: docked PiChat, or the host's floating surface over the same controller (with the toggle in its header).
  const header = typeof controls === 'function' ? controls({ panelOpen }) : controls ?? chat.controls;
  const chatProps: PiChatProps | undefined = controller && { ...chat, controller, artifacts, ...(conversations ? { conversations, historyList: false } : {}),
    headerStart: <>{toggle}{chat.headerStart}</>, ...(header === undefined ? {} : { controls: header }) };
  const docked_chat = <div data-testid="workspace-center" className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">
    {chatTop}
    <div className="relative flex min-h-0 flex-1 flex-col">
      {chatProps ? <PiChat key={conversationId} {...chatProps} headerStart={<>{toggleSpace}{chat.headerStart}</>} className={cn('min-h-0 flex-1', chat.className)} />
        // Same geometry as the PiChat header, so nothing moves when the chat arrives.
        : <>{toggle && <div className="flex shrink-0 items-center gap-2 border-b border-border px-3 py-2 sm:gap-3 sm:px-4 sm:py-2.5">{toggleSpace}</div>}{connecting}</>}
      {toggle && <div ref={toggleRow} className="pointer-events-none absolute top-0 left-0 z-10 flex items-center px-3 sm:px-4 [&>*]:pointer-events-auto">{toggle}</div>}
    </div>
  </div>;

  const kind = active ? 'artifact' : file ? 'file' : host?.kind;
  const shown = active ?? file ?? host;
  const actionsFor = (floatChat: (() => void) | undefined): readonly BlockAction[] => [
    ...(floatChat ? [{ id: 'float-chat', label: text.labels.floatChat, icon: text.icons.floatChat, placement: 'menu' as const, onSelect: floatChat }] : []),
    ...(shown ? typeof panelActions === 'function' ? panelActions(shown) : panelActions ?? [] : []),
  ];
  return <AppTextProvider value={text}><ChatTextProvider value={chatText}><div ref={root} data-boring="agent-workspace" data-sessions={!conversations ? undefined : narrow ? (drawer ? 'drawer' : 'closed') : docked ? 'docked' : 'hidden'}
    className={cn('relative flex h-full min-h-0 min-w-0 flex-1 overflow-hidden', className)}>
    {conversations && (docked || (narrow && drawer)) && <SessionsPane conversations={conversations} drawer={narrow} onClose={() => setDrawer(false)} />}
    <ArtifactWorkspace open={panelOpen} onClose={close} panelLabel={text.labels.artifactPanel} labels={{ resize: text.labels.resizePanel, floatHint: text.labels.floatHint }} fullscreen={fullscreen} onFullscreenChange={setFullscreen} storageKey={`${storageKey}.panel-width`}
      sheetBelow={docked ? Math.max(0, sheetBelow - SESSIONS_WIDTH) : sheetBelow} {...(floatBelow === undefined ? {} : { floatBelow })}
      chat={layout => layout.floating && floatingChat && chatProps ? floatingChat(chatProps, layout.dock) : docked_chat}
      panel={win => <ViewerWindowProvider value={{ fullscreen: win.fullscreen, onFullscreenChange: win.onFullscreenChange, actions: actionsFor(win.floatChat), labels: text.labels, icons: text.icons }}>
        <div data-testid="viewer-panel" data-kind={kind} className="flex min-h-0 flex-1 flex-col overflow-hidden [&>*]:min-h-0 [&>*]:flex-1">
          {active
            ? <ArtifactPanel key={artifactKey(active.descriptor)} active={active} versions={newestOf(artifactKey(active.descriptor))} options={options} onClose={win.close}
                onSelect={value => {
                  const known = newestOf(artifactKey(active.descriptor));
                  setOpened({ kind: 'artifact', conversation: active.conversation, follow: value === 'latest', descriptor: value === 'latest' ? (known[0] ?? active.descriptor) : { ...active.descriptor, revision: value } });
                }} />
            : file ? <FileViewer key={file.path} path={file.path} locator={locate(file.path)} options={options} onClose={win.close} {...(fileBack ? { onBack: fileBack.onBack, backLabel: fileBack.label } : {})} />
            : host ? panels![host.kind]!(host, win) : null}
        </div></ViewerWindowProvider>} />
  </div></ChatTextProvider></AppTextProvider>;
}

'use client';

import { useEffect } from 'react';
import { Button } from '../button/button';
import { useAppText } from './app-labels';
import { ConversationList } from '../pi-chat/pi-chat';
import type { ConversationsConfig } from '../pi-chat/pi-chat';
import { cn } from '../utils/utils';

/**
 * The sessions pane: a title with New, then the searchable conversation list of `pi-chat` (`ConversationList`: search, Archived filter,
 * rename, archive, delete). Docked at the left on a wide screen; a drawer over the page with a backdrop on a narrow one, closed by
 * Escape, the backdrop, the close button or choosing a conversation.
 */
export function SessionsPane({ conversations, title: givenTitle, drawer, onClose }: {
  readonly conversations: ConversationsConfig;
  readonly title?: string;
  /** Rendered as a drawer (narrow screens). */
  readonly drawer: boolean;
  /** Closes the drawer; absent when docked. */
  readonly onClose?: (() => void) | undefined;
}) {
  const { labels, icons } = useAppText();
  const title = givenTitle ?? labels.sessionsTitle;
  useEffect(() => {
    if (!drawer || !onClose) return;
    const escape = (event: KeyboardEvent) => { if (event.key === 'Escape' && !event.defaultPrevented) onClose(); };
    document.addEventListener('keydown', escape);
    return () => document.removeEventListener('keydown', escape);
  }, [drawer, onClose]);
  const picked = drawer ? onClose : undefined;
  return <>
    {drawer && <button type="button" tabIndex={-1} aria-hidden="true" data-testid="sessions-backdrop" onClick={onClose} className="fixed inset-0 z-40 cursor-default bg-black/40" />}
    <aside data-testid="conversations" data-drawer={drawer ? 'true' : 'false'} aria-label={title} {...(drawer ? { role: 'dialog', 'aria-modal': true } : {})}
      className={cn('pi-chat flex min-h-0 flex-col bg-background text-foreground', drawer
        ? 'fixed inset-y-0 left-0 z-50 w-[min(20rem,85vw)] border-r border-border shadow-xl pt-[env(safe-area-inset-top)] pb-[env(safe-area-inset-bottom)]'
        : 'w-72 shrink-0 border-r border-border')}>
      <header className="flex shrink-0 items-center gap-2 border-b border-border px-3 py-2">
        <h2 className="m-0 min-w-0 flex-1 truncate text-sm font-semibold tracking-tight">{title}</h2>
        {conversations.onNew && <Button size="sm" variant="outline" data-testid="conversation-new" onClick={() => { conversations.onNew!(); picked?.(); }}><icons.newChat className="size-3.5" aria-hidden="true" />{labels.newChat}</Button>}
        {drawer && onClose && <Button size="icon-sm" variant="ghost" aria-label={labels.closeSessions} title={labels.close} data-testid="sessions-close" onClick={onClose}><icons.closeSessions className="size-4" aria-hidden="true" /></Button>}
      </header>
      <ConversationList conversations={conversations} onPicked={picked} />
    </aside>
  </>;
}

/** The chat header's button that shows or hides the sessions pane (opens the drawer on a narrow screen). */
export function SessionsToggle({ open, drawer, onToggle }: { readonly open: boolean; readonly drawer: boolean; readonly onToggle: () => void }) {
  const { labels, icons } = useAppText();
  const label = drawer ? labels.openSessions : open ? labels.hideSessions : labels.showSessions;
  return <Button size="icon-sm" variant="ghost" data-testid="sessions-toggle" aria-label={label} title={label} aria-expanded={open} onClick={onToggle} className="-ml-1 shrink-0 text-muted-foreground">
    <icons.sessionsToggle className="size-4" aria-hidden="true" />
  </Button>;
}

'use client';

// The artifact panel: the standard viewer bar (title, type, version switcher, Refresh, Share, copy, download, close) over the viewer for
// the artifact's type. It follows the latest saved revision while nothing is unsaved ("Latest") or pins one older version, read-only. It
// lists the versions the host's workspace provider retains for the file (`history`) and reads through the host's resource client. It never
// executes artifact content (HTML runs only in the viewers' sandboxed preview when the host passes `interactive`).
import { useEffect, useMemo, useState, useSyncExternalStore } from 'react';
import type { ReactNode } from 'react';
import { CodeXmlIcon, EyeIcon } from 'lucide-react';
import { randomUUID } from '@hachej/boring-files/platform';
import type { ResourceClient, ResourceSnapshot } from '@hachej/boring-files';
import type { ResourceIdentity } from '@hachej/boring-files/remote';
import { createMarkdownController } from '@hachej/boring-ui-kit/markdown';
import type { MarkdownController } from '@hachej/boring-ui-kit/markdown';
import { createHtmlController } from '@hachej/boring-ui-kit/html';
import type { HtmlController } from '@hachej/boring-ui-kit/html';
import type { NativeChatController } from '@hachej/boring-ui-kit/native-chat';
import { artifactKey, collectArtifacts } from '../pi-chat/pi-chat';
import type { ArtifactDescriptor, ArtifactTarget, ArtifactsConfig } from '../pi-chat/pi-chat';
import { CodeBlock } from '../pi-chat/code-block';
import { typeLabel } from '../pi-chat/artifact';
import { HtmlPane } from '../viewers/html-pane';
import { MarkdownPane } from '../viewers/markdown-pane';
import { ViewerFrame, ViewerToggle } from '../viewers/viewer-frame';
import type { ViewerFrameProps, ViewerShare } from '../viewers/viewer-frame';
import { ViewerVersions } from '../viewers/menu';
import type { InteractiveHtml } from '../viewers/interactive-html';
import { downloadFile } from '../viewers/download';
import { copyText } from '../utils/utils';
import { savedLabel, useSaved } from './use-saved';
import { useAppText } from './app-labels';

const NOOP = () => () => {};
const POLL_MS = 1500;
const EXTENSION = /\.([A-Za-z0-9]{1,8})$/;

/** One retained revision of a file with its save time (`files.saves(path)` of `@hachej/boring-files/workspace`). */
export interface SavedRevision { readonly revision: string; readonly savedAt: number }

/** What a host viewer for an artifact type or file kind the block does not render itself (for example a tldraw canvas) receives. */
export interface CustomViewerProps {
  readonly target: ArtifactTarget;
  readonly title: string;
  /** A pinned revision, read-only; absent: follow the latest. */
  readonly revision?: string | undefined;
  /** Pass these on to the `ViewerFrame` around it: test ids, the version switcher or back button, Close, the share target. */
  readonly frame: Pick<ViewerFrameProps, 'testId' | 'titleTestId' | 'controls' | 'onClose' | 'target'>;
}
/** Host viewers by artifact type or file kind (`canvas`, or any other). They take precedence over the built-in ones. */
export type CustomViewers = Readonly<Record<string, (props: CustomViewerProps) => ReactNode>>;

/** Everything a viewer in the panel reads through: one resource client, the version history, host viewers and policy. */
export interface ViewerOptions {
  readonly client: ResourceClient;
  readonly identity: ResourceIdentity;
  readonly history?: ((path: string) => Promise<readonly SavedRevision[]>) | undefined;
  readonly viewers?: CustomViewers | undefined;
  /** The host's opt-in to running HTML pages in the sandboxed preview. */
  readonly interactive?: InteractiveHtml | undefined;
  readonly share?: ViewerShare | undefined;
}

/** Every artifact version the conversation's tool results produced (the version switcher's source), oldest first. */
export function useArtifactVersions(controller: NativeChatController | undefined, detect?: ArtifactsConfig['detect']): ArtifactDescriptor[] {
  const view = useSyncExternalStore(controller ? controller.subscribe : NOOP, () => controller?.getSnapshot().view, () => undefined);
  return useMemo(() => collectArtifacts(view, detect), [view, detect]);
}

/** How many messages the person has sent in the conversation: it changes when a new turn starts. */
export function useTurn(controller: NativeChatController | undefined): number {
  const view = useSyncExternalStore(controller ? controller.subscribe : NOOP, () => controller?.getSnapshot().view, () => undefined);
  return useMemo(() => (view?.entries ?? []).reduce((count, entry) => count + (entry.model ?? []).filter(message => message.role === 'user').length, 0), [view]);
}

/** The revisions the workspace provider retains for a file with their save times, newest first; followed while the panel is open. */
function useHistory(history: ViewerOptions['history'], path: string): readonly SavedRevision[] {
  const [revisions, setRevisions] = useState<readonly SavedRevision[]>([]);
  useEffect(() => {
    if (!history) return;
    let cancelled = false;
    const key = (saves: readonly SavedRevision[]) => saves.map(save => `${save.revision}@${save.savedAt}`).join();
    const load = () => history(path).then(saves => { if (!cancelled) setRevisions(current => key(current) === key(saves) ? current : saves); }).catch(() => {});
    void load();
    const timer = setInterval(load, POLL_MS);
    return () => { cancelled = true; clearInterval(timer); };
  }, [history, path]);
  return revisions;
}

interface VersionMenu {
  readonly items: readonly { readonly id: string; readonly label: string; readonly latest: boolean }[];
  readonly current: string;
  /** Position counted from the oldest retained revision: only a test hook. */
  readonly number: number | undefined;
  readonly savedAt: number | undefined;
}

/** The version menu, newest first: each retained revision is named by when it was saved, and the newest is "Latest". The pin is the revision. */
function versionMenu(artifact: ArtifactDescriptor, follow: boolean, revisions: readonly SavedRevision[], earlier: string): VersionMenu {
  const at = follow ? 0 : revisions.findIndex(save => save.revision === artifact.revision);
  const shown = at < 0 ? undefined : revisions[at];
  return { items: revisions.map((save, index) => ({ id: index === 0 ? 'latest' : save.revision, label: savedLabel(save.savedAt, Date.now(), earlier), latest: index === 0 })),
    current: follow ? 'latest' : artifact.revision, number: shown ? revisions.length - at : undefined, savedAt: shown?.savedAt };
}

function SvgView({ text, title, frame }: { readonly text: string; readonly title: string; readonly frame: ViewerFrameProps }) {
  const { labels } = useAppText();
  const [mode, setMode] = useState<'preview' | 'source'>('preview');
  // An SVG is shown only as an image from a blob URL: it never becomes markup in this page, so its scripts cannot run.
  const url = useMemo(() => URL.createObjectURL(new Blob([text], { type: 'image/svg+xml' })), [text]);
  useEffect(() => () => URL.revokeObjectURL(url), [url]);
  return <ViewerFrame {...frame} controls={<>
    <ViewerToggle label={labels.view} value={mode} onChange={setMode} options={[
      { id: 'preview', label: labels.preview, text: labels.preview, icon: <EyeIcon className="size-4" aria-hidden="true" />, testId: 'artifact-mode' },
      { id: 'source', label: labels.source, text: labels.source, icon: <CodeXmlIcon className="size-4" aria-hidden="true" />, testId: 'artifact-mode' }]} />
    {frame.controls}</>}>
    {mode === 'preview'
      ? <div className="boring-viewer-checker flex min-h-0 flex-1 items-center justify-center overflow-auto bg-white p-6"><img data-testid="artifact-svg" src={url} alt={title} className="max-h-full max-w-full" /></div>
      : <div className="min-h-0 flex-1 overflow-auto p-3"><CodeBlock code={text} language="svg" /></div>}
  </ViewerFrame>;
}

type DocumentController = MarkdownController | HtmlController;

/** One artifact version's frame and body. Mounted per resource and revision, so switching version starts clean. */
function Version({ artifact, pinned, menu, options, onSelect, onClose }: {
  readonly artifact: ArtifactDescriptor; readonly pinned: boolean; readonly menu: VersionMenu; readonly options: ViewerOptions;
  readonly onSelect: (value: string) => void; readonly onClose: () => void;
}) {
  const { type } = artifact;
  const { client, identity } = options;
  const { labels } = useAppText();
  const path = artifact.target.resource.path;
  const custom = options.viewers?.[type];
  const create = useMemo(() => {
    const base = (snapshot: ResourceSnapshot) => ({ identity, client, instanceId: randomUUID(), epoch: 'workspace', source: { kind: 'saved' as const, snapshot } });
    if (custom) return undefined;
    if (type === 'markdown') return (snapshot: ResourceSnapshot): DocumentController => createMarkdownController({ ...base(snapshot), readOnly: pinned });
    if (type === 'html') return (snapshot: ResourceSnapshot): DocumentController => createHtmlController({ ...base(snapshot), readOnly: true });
    return undefined;
  }, [type, pinned, client, identity, custom]);
  const saved = useSaved<DocumentController>({ client, target: artifact.target, revision: pinned ? artifact.revision : undefined, create });
  const controller = saved.controller;
  // The text to copy and download is the buffer when a viewer holds one, so the person's unsaved edits are included.
  const text = useSyncExternalStore(controller ? controller.subscribe : NOOP, () => controller ? controller.getSnapshot().text : saved.text, () => saved.text);
  const extension = EXTENSION.exec(path)?.[1] ?? 'txt';
  const revision = saved.kind === 'open' ? saved.snapshot.ref.revision : pinned ? artifact.revision : undefined;
  // The history menu: newest first, the newest marked "Latest" (choosing it follows the latest), the one on display checked.
  const versions = menu.items.length > 1 ? <ViewerVersions testId="artifact-versions" current={menu.current} onSelect={onSelect} versions={menu.items} /> : undefined;
  const target = { artifact: artifactKey(artifact), version: pinned ? artifact.revision : 'latest' };
  const frame = {
    title: artifact.title, testId: 'artifact', titleTestId: 'artifact-panel-title', controls: versions, onClose, target, ...(revision === undefined ? {} : { revision }), ...(options.share ? { onShare: options.share } : {}),
    subtitle: <>
      <span data-testid="artifact-panel-type">{typeLabel(artifact)}</span>
      <span aria-hidden="true">·</span>
      <span data-testid="artifact-panel-version">{pinned ? (menu.savedAt !== undefined ? labels.savedAt(savedLabel(menu.savedAt, Date.now(), labels.earlierVersion)) : labels.olderVersion) : menu.savedAt ? labels.latestSavedAt(savedLabel(menu.savedAt, Date.now(), labels.earlierVersion)) : labels.latest}</span>
    </>,
    ...(pinned ? { status: { label: labels.readOnly, kind: 'read-only' as const } } : {}),
  };
  const filename = `${artifact.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'artifact'}.${extension}`;
  const body = (children: ReactNode) => <div data-testid="artifact-body" data-state={saved.kind} className="flex h-full min-h-0 flex-1 flex-col overflow-hidden">{children}</div>;
  if (custom) return body(custom({ target: artifact.target, title: artifact.title, ...(pinned ? { revision: artifact.revision } : {}), frame: { testId: 'artifact', titleTestId: 'artifact-panel-title', controls: versions, onClose, target } }));
  // Until the version is open the bar offers no Share: the pane that shows it brings its own frame, so this one is replaced (remounted)
  // when it opens, and a Share pressed just then would copy the link with its "Link copied" notice lost with the old frame.
  if (saved.kind !== 'open') {
    const { onShare: _, ...waiting } = frame;
    return body(<ViewerFrame {...waiting}><p className="m-0 p-4 text-sm text-muted-foreground" role="status">{saved.kind === 'loading' ? labels.loading : saved.kind === 'invalid' ? labels.artifactNotText : labels.versionUnavailable}</p></ViewerFrame>);
  }
  const document = (children: ReactNode) => <div data-testid="document" data-revision={saved.snapshot.ref.revision} className="h-full min-h-0">{children}</div>;
  if (type === 'markdown' && controller) return body(document(<MarkdownPane controller={controller as MarkdownController} initialMode="rich" {...frame} />));
  if (type === 'html' && controller) return body(document(<HtmlPane controller={controller as HtmlController} {...(options.interactive ? { interactive: options.interactive } : {})} {...frame} />));
  const actions = { onCopy: () => copyText(text ?? ''), onDownload: () => downloadFile(filename, text ?? '', `${artifact.mediaType};charset=utf-8`) };
  if (type === 'svg') return body(<SvgView text={saved.text} title={artifact.title} frame={{ ...frame, ...actions }} />);
  if (type === 'canvas') return body(<ViewerFrame {...frame}><p className="m-0 p-4 text-sm text-muted-foreground" role="status">{labels.noCanvasViewer}</p></ViewerFrame>);
  return body(<ViewerFrame {...frame} {...actions}><div className="min-h-0 flex-1 overflow-auto p-3"><CodeBlock code={saved.text} language={artifact.language ?? 'text'} /></div></ViewerFrame>);
}

/**
 * One artifact in the panel. `active.follow` shows the latest saved revision under the newest known title (`versions`: every version of
 * this file the conversation presented or saved, newest first); otherwise the one revision in `active.descriptor` is pinned and read-only.
 * `onSelect` receives `latest` or a revision from the version menu.
 */
export function ArtifactPanel({ active, versions, options, onSelect, onClose }: {
  readonly active: { readonly descriptor: ArtifactDescriptor; readonly follow: boolean };
  readonly versions: readonly ArtifactDescriptor[];
  readonly options: ViewerOptions;
  readonly onSelect: (value: string) => void;
  readonly onClose: () => void;
}) {
  const { follow } = active;
  const artifact = follow ? versions[0] ?? active.descriptor : active.descriptor;
  const path = artifact.target.resource.path;
  const revisions = useHistory(options.history, path);
  const { labels } = useAppText();
  const menu = versionMenu(artifact, follow, revisions, labels.earlierVersion);
  return <div data-testid="artifact-panel" data-artifact-id={artifactKey(artifact)} data-artifact-type={artifact.type} data-follow={follow ? 'true' : 'false'} data-artifact-position={menu.number} data-artifact-revision={follow ? undefined : artifact.revision}
    className="pi-chat flex h-full min-h-0 flex-col">
    <Version key={`${path}@${follow ? 'latest' : artifact.revision}`} artifact={artifact} pinned={!follow} menu={menu} options={options} onSelect={onSelect} onClose={onClose} />
  </div>;
}

'use client';

// Opens one workspace file in the viewer that suits its type, always in the standard viewer frame (viewers item): Markdown and HTML in
// their editors (revisioned through the host's resource client, so saves go back to the file and an edit made behind the editor's back is
// a conflict), images and PDFs read-only from the file's bytes, anything else as text. A host viewer (`viewers[kind]`) takes precedence.
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import { randomUUID } from '@hachej/boring-files/platform';
import type { ResourceLocator, ResourceSnapshot } from '@hachej/boring-files';
import { createMarkdownController } from '@hachej/boring-ui-kit/markdown';
import type { MarkdownController } from '@hachej/boring-ui-kit/markdown';
import { createHtmlController } from '@hachej/boring-ui-kit/html';
import type { HtmlController } from '@hachej/boring-ui-kit/html';
import { HtmlPane } from '../viewers/html-pane';
import { ImagePane } from '../viewers/image-pane';
import { MarkdownPane } from '../viewers/markdown-pane';
import { PdfPane } from '../viewers/pdf-pane';
import { ViewerFrame } from '../viewers/viewer-frame';
import { downloadFile } from '../viewers/download';
import { formatBytes } from '../viewers/media';
import { copyText } from '../utils/utils';
import { KIND_LABEL, decodeText, kindOf, mediaTypeOf } from './file-kinds';
import type { FileKind } from './file-kinds';
import type { ViewerOptions } from './artifact-panel';
import { useSaved } from './use-saved';
import { useAppText } from './app-labels';

const POLL_MS = 1500;
const nameOf = (path: string) => path.split('/').pop() || path;

interface Common {
  readonly path: string;
  readonly kind: FileKind;
  readonly locator: ResourceLocator;
  readonly options: ViewerOptions;
  readonly onClose: () => void;
  readonly back: ReactNode;
}

const subtitleOf = (locator: ResourceLocator) => <span data-testid="file-path" className="truncate">{locator.resource.path}</span>;

/** Markdown or HTML: a revisioned controller over the file. A new revision remounts the pane; it starts in the mode the person chose. */
function FileDocument({ path, kind, locator, options, onClose, back }: Common) {
  const { client, identity } = options;
  const create = useMemo(() => (snapshot: ResourceSnapshot): MarkdownController | HtmlController => (kind === 'markdown' ? createMarkdownController : createHtmlController)({
    identity, client, instanceId: randomUUID(), epoch: 'workspace', source: { kind: 'saved', snapshot } }), [kind, client, identity]);
  const saved = useSaved({ client, target: locator, create });
  const { labels } = useAppText();
  const [mode, setMode] = useState<string>(kind === 'markdown' ? 'rich' : 'preview');
  const common = { title: nameOf(path), subtitle: subtitleOf(locator), target: { file: path }, onClose, titleTestId: 'file-title', controls: back, ...(options.share ? { onShare: options.share } : {}) };
  // Until the document is open the bar offers no Share, Copy or menu actions of its own: they would act on a document that is not shown.
  if (saved.kind !== 'open' || !saved.controller) {
    return <ViewerFrame title={common.title} subtitle={common.subtitle} onClose={onClose} controls={back}>
      <p role="status" className="m-0 p-4 text-sm text-muted-foreground">{saved.kind === 'loading' ? labels.loading : saved.kind === 'missing' ? labels.fileMissing : labels.fileNotText}</p>
    </ViewerFrame>;
  }
  const revision = saved.snapshot.ref.revision;
  // The preview selector the journeys use keeps working: the wrapper holds the document's text.
  return <div data-testid="file-preview" className="h-full min-h-0" data-revision={revision}>
    {kind === 'markdown'
      ? <MarkdownPane key={revision} controller={saved.controller as MarkdownController} revision={revision} initialMode={mode as 'rich'} onModeChange={setMode} {...common} />
      : <HtmlPane key={revision} controller={saved.controller as HtmlController} revision={revision} initialMode={mode as 'preview'} onModeChange={setMode} {...(options.interactive ? { interactive: options.interactive } : {})} {...common} />}
  </div>;
}

type Loaded = { readonly kind: 'loading' | 'missing' } | { readonly kind: 'ready'; readonly bytes: Uint8Array; readonly revision: string; readonly text: string | undefined };

/** Image, PDF and text files: read through the resource client, refreshed on demand (and followed while open, for text). */
function FileBytes({ path, kind, locator, options, onClose, back }: Common) {
  const { labels } = useAppText();
  const [file, setFile] = useState<Loaded>({ kind: 'loading' });
  const held = useRef(file);
  held.current = file;
  const load = useCallback(async () => {
    const read = await options.client.read({ target: locator, revision: { kind: 'latest' } });
    if (read.kind !== 'available') { if (held.current.kind === 'loading') setFile({ kind: 'missing' }); return; }
    const { bytes, ref } = read.snapshot;
    setFile(current => current.kind === 'ready' && current.revision === ref.revision ? current : { kind: 'ready', bytes, revision: ref.revision, text: decodeText(path, bytes) });
  }, [options.client, locator, path]);
  useEffect(() => {
    let cancelled = false;
    const run = () => load().catch(() => { if (!cancelled && held.current.kind === 'loading') setFile({ kind: 'missing' }); });
    void run();
    // Text follows the workspace while open; media is read again when the person presses Refresh.
    const timer = kind === 'text' ? setInterval(run, POLL_MS) : undefined;
    return () => { cancelled = true; clearInterval(timer); };
  }, [load, kind]);
  const common = { subtitle: subtitleOf(locator), target: { file: path }, onClose, titleTestId: 'file-title', controls: back, ...(options.share ? { onShare: options.share } : {}) };
  // Until the file is read the bar offers no Share: the image and PDF panes bring their own frame, so this one is replaced (remounted)
  // when the bytes arrive, and a Share pressed just then would copy the link with its "Link copied" notice lost with the old frame.
  if (file.kind !== 'ready') {
    return <ViewerFrame title={nameOf(path)} subtitle={common.subtitle} onClose={onClose} titleTestId="file-title" controls={back}>
      <p role="status" className="m-0 p-4 text-sm text-muted-foreground">{file.kind === 'loading' ? labels.loading : labels.fileMissing}</p>
    </ViewerFrame>;
  }
  if (kind === 'image') return <ImagePane name={nameOf(path)} mediaType={mediaTypeOf(path)} bytes={file.bytes} onRefresh={load} {...common} />;
  if (kind === 'pdf') return <PdfPane name={nameOf(path)} bytes={file.bytes} onRefresh={load} {...common} />;
  const { text } = file, size = file.bytes.byteLength;
  return <ViewerFrame title={nameOf(path)} {...common} subtitle={<>{subtitleOf(locator)}<span aria-hidden="true">·</span><span>{formatBytes(size)}</span></>}
    onRefresh={load} {...(text === undefined ? {} : { onCopy: () => copyText(text), onDownload: () => downloadFile(nameOf(path), text, 'text/plain;charset=utf-8') })}>
    {text === undefined
      ? <p role="status" className="m-0 p-4 text-sm text-muted-foreground">{labels.binaryFile(formatBytes(size))}</p>
      : <div className="min-h-0 flex-1 overflow-auto p-3"><pre data-testid="file-preview" className="m-0 rounded-lg bg-muted p-3 font-mono text-[13px] leading-relaxed break-words whitespace-pre-wrap">{text}</pre></div>}
  </ViewerFrame>;
}

/**
 * One file in the panel. `path` is the host's name for it (shown in the share target and `data-path`); `locator` is the resource the
 * client reads. Remount per file with a `key`. `onBack` adds a back button to the bar (for example to the host's file list).
 */
export function FileViewer({ path, locator, options, onClose, onBack, backLabel }: {
  readonly path: string;
  readonly locator: ResourceLocator;
  readonly options: ViewerOptions;
  readonly onClose: () => void;
  readonly onBack?: (() => void) | undefined;
  readonly backLabel?: string | undefined;
}) {
  const kind = kindOf(path);
  const { labels, icons } = useAppText();
  const back = onBack ? <button type="button" data-testid="file-back" onClick={onBack} className="inline-flex h-10 cursor-pointer items-center gap-1 rounded-lg border border-border bg-background px-2 text-sm md:h-8 md:text-xs"><icons.back className="size-3.5" aria-hidden="true" />{backLabel ?? labels.back}</button> : undefined;
  const custom = options.viewers?.[kind];
  const common: Common = { path, kind, locator, options, onClose, back };
  return <div data-testid="file-viewer" data-kind={kind} data-path={path} aria-label={labels.fileViewer(KIND_LABEL[kind])} className="flex h-full min-h-0 flex-col overflow-hidden [&>*]:min-h-0 [&>*]:flex-1">
    {custom ? custom({ target: locator, title: nameOf(path), frame: { titleTestId: 'file-title', onClose, target: { file: path }, controls: back } })
      : kind === 'markdown' || kind === 'html' ? <FileDocument {...common} />
      : kind === 'canvas' ? <ViewerFrame title={nameOf(path)} subtitle={subtitleOf(locator)} onClose={onClose} controls={back}><p role="status" className="m-0 p-4 text-sm text-muted-foreground">{labels.noCanvasViewer}</p></ViewerFrame>
      : <FileBytes {...common} />}
  </div>;
}

/** Which viewer opens a file: `markdown`, `html`, `canvas`, `image`, `pdf` or `text` (anything else, shown as text when it decodes). */
export type FileKind = 'markdown' | 'html' | 'canvas' | 'image' | 'pdf' | 'text';

const TYPES: Readonly<Record<string, readonly [string, FileKind]>> = {
  md: ['text/markdown', 'markdown'], markdown: ['text/markdown', 'markdown'],
  html: ['text/html', 'html'], htm: ['text/html', 'html'],
  png: ['image/png', 'image'], jpg: ['image/jpeg', 'image'], jpeg: ['image/jpeg', 'image'], gif: ['image/gif', 'image'], webp: ['image/webp', 'image'], svg: ['image/svg+xml', 'image'],
  pdf: ['application/pdf', 'pdf'], tldraw: ['application/vnd.tldraw+json', 'canvas'],
  txt: ['text/plain', 'text'], json: ['application/json', 'text'], csv: ['text/csv', 'text'], js: ['text/javascript', 'text'], mjs: ['text/javascript', 'text'], css: ['text/css', 'text'],
};

export const extensionOf = (path: string): string => /\.([A-Za-z0-9]{1,8})$/.exec(path)?.[1]?.toLowerCase() ?? '';
/** The IANA media type for a path, `application/octet-stream` when unknown. */
export const mediaTypeOf = (path: string): string => TYPES[extensionOf(path)]?.[0] ?? 'application/octet-stream';
export const kindOf = (path: string): FileKind => TYPES[extensionOf(path)]?.[1] ?? 'text';
export const KIND_LABEL: Readonly<Record<FileKind, string>> = { markdown: 'Markdown', html: 'HTML', canvas: 'Canvas', image: 'Image', pdf: 'PDF', text: 'Text' };

/** The text of a file, or `undefined` when it is binary: an image or PDF kind (SVG excepted), a NUL byte, or bytes that are not UTF-8. */
export function decodeText(path: string, bytes: Uint8Array): string | undefined {
  if ((['image', 'pdf'].includes(kindOf(path)) && extensionOf(path) !== 'svg') || bytes.includes(0)) return undefined;
  try { return new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes); } catch { return undefined; }
}

import { useEffect, useLayoutEffect, useMemo, useState } from 'react';
import type { ResourceClient, ResourceLocator, ResourceSnapshot } from '@hachej/boring-files';

const POLL_MS = 1500;
const readText = (bytes: Uint8Array): string | undefined => { try { return new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes); } catch { return undefined; } };

/** What a viewer controller exposes to `useSaved`: its buffer state (never replaced while dirty or saving) and teardown. */
export interface SavedController {
  readonly getSnapshot: () => { readonly dirty?: boolean; readonly save?: { readonly kind: string }; readonly base?: { readonly kind: string; readonly target?: object } };
  readonly dispose: () => void;
}

export type SavedState<C extends SavedController> =
  | { readonly kind: 'loading' | 'missing' | 'denied' | 'unavailable' | 'invalid'; readonly text?: undefined; readonly controller?: undefined }
  | { readonly kind: 'open'; readonly snapshot: ResourceSnapshot; readonly text: string; readonly controller: C | undefined };

/**
 * The saved text of one resource: the latest revision (polled while the local buffer is clean, never replacing unsaved
 * edits) or one exact revision read once. `create` may return a viewer controller for each saved snapshot; it is disposed when
 * a newer revision replaces it and on unmount.
 */
export function useSaved<C extends SavedController = SavedController>({ client, target, revision, create }: {
  readonly client: ResourceClient;
  readonly target: ResourceLocator;
  readonly revision?: string | undefined;
  readonly create?: ((snapshot: ResourceSnapshot) => C) | undefined;
}): SavedState<C> {
  const key = JSON.stringify([target.resource.providerId, target.resource.path, target.view.kind, target.view.kind === 'working' ? target.view.viewId : null, revision]);
  const binding = useMemo(() => ({ client, key, create }), [client, key]); // eslint-disable-line react-hooks/exhaustive-deps
  useLayoutEffect(() => { binding.create = create; }, [binding, create]);
  const [stored, setStored] = useState<{ readonly binding: typeof binding; readonly state: SavedState<C> }>();
  useEffect(() => {
    let cancelled = false, reading = false;
    let state: SavedState<C> = { kind: 'loading' };
    const update = (next: SavedState<C>) => { state = next; setStored({ binding, state }); };
    update(state);
    const follow = async () => {
      if (cancelled || reading) return;
      const now = state;
      const before = now.kind === 'open' ? now.controller?.getSnapshot() : undefined;
      if (before && (before.dirty || before.save?.kind === 'pending')) return;
      reading = true;
      let read;
      try { read = await client.read({ target, revision: revision ? { kind: 'exact', value: revision } : { kind: 'latest' } }).catch(() => undefined); }
      finally { reading = false; }
      if (cancelled || !read || state !== now) return;
      const local = now.kind === 'open' ? now.controller?.getSnapshot() : undefined;
      if (local !== before) return;
      if (read.kind !== 'available') { if (now.kind !== 'open') update({ kind: read.kind }); return; }
      if (now.kind === 'open') {
        if (now.snapshot.ref.revision === read.snapshot.ref.revision) return;
        if (local?.base?.kind === 'revision' && (local.base.target as { readonly revision?: string } | undefined)?.revision === read.snapshot.ref.revision) return;
        now.controller?.dispose();
      }
      const text = readText(read.snapshot.bytes);
      if (text === undefined) { update({ kind: 'invalid' }); return; }
      let controller: C | undefined;
      try { controller = binding.create?.(read.snapshot); } catch { update({ kind: 'invalid' }); return; }
      update({ kind: 'open', snapshot: read.snapshot, text, controller });
    };
    void follow();
    const timer = revision ? undefined : setInterval(() => { void follow(); }, POLL_MS);
    return () => { cancelled = true; clearInterval(timer); state.controller?.dispose(); };
  }, [binding]); // eslint-disable-line react-hooks/exhaustive-deps
  return stored?.binding === binding ? stored.state : { kind: 'loading' };
}

/** A save time for a person: the clock time (with seconds, so two quick saves differ) today, the date as well on another day. */
export function savedLabel(savedAt: number | undefined, now = Date.now(), earlier = 'Earlier version'): string {
  if (!savedAt) return earlier;
  const day = (value: number) => new Date(value).toDateString();
  return new Date(savedAt).toLocaleString([], day(savedAt) === day(now) ? { timeStyle: 'medium' } : { dateStyle: 'medium', timeStyle: 'medium' });
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { ConversationItem, ConversationsConfig } from '../pi-chat/pi-chat';

/** One row as `createConversationsHandler` of `@hachej/boring-agent/conversations` returns it. */
interface ServedConversation {
  readonly id: number | string;
  readonly title: string | null;
  readonly lastMessage: string | null;
  readonly updatedAt: number;
  readonly archived: boolean;
}

const item = (served: ServedConversation): ConversationItem => ({ id: String(served.id), title: served.title ?? undefined, updatedAt: served.updatedAt, lastMessage: served.lastMessage, archived: served.archived });

/**
 * The sessions list over the host's conversations handler (`createConversationsHandler` of `@hachej/boring-agent/conversations`, mounted at
 * `endpoint`): the active list (polled every `pollMs` while mounted), server-side search with the Archived filter, New, rename, archive,
 * delete and fork. New and fork select the conversation they made through `onSelect`. `onChange` runs after every change the person made
 * (the host may reload what depends on the list). `fetch` is the host's authenticated fetch. Returns `undefined` until the first list arrives.
 */
export function useConversations({ endpoint, fetch, activeId, onSelect, onChange, pollMs = 4000 }: {
  /** Undefined: nothing is listed yet (for example while the host is still loading). */
  readonly endpoint: string | URL | undefined;
  readonly fetch: (request: Request) => Promise<Response>;
  readonly activeId: string | undefined;
  readonly onSelect: (id: string) => void;
  readonly onChange?: (() => void | Promise<void>) | undefined;
  readonly pollMs?: number;
}): (ConversationsConfig & { readonly reload: () => Promise<void> }) | undefined {
  const [items, setItems] = useState<readonly ConversationItem[] | undefined>();
  const latest = useRef({ fetch, onSelect, onChange, activeId });
  latest.current = { fetch, onSelect, onChange, activeId };
  const base = endpoint === undefined ? undefined : String(endpoint);
  const call = useCallback(async (params: Record<string, string>, body?: unknown, signal?: AbortSignal) => {
    if (base === undefined) throw new Error('No conversations endpoint');
    const url = new URL(base, globalThis.location?.href);
    for (const [key, value] of Object.entries(params)) url.searchParams.set(key, value);
    const init: RequestInit = body === undefined ? { ...(signal ? { signal } : {}) } : { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body), ...(signal ? { signal } : {}) };
    const response = await latest.current.fetch(new Request(url, init));
    if (!response.ok) throw new Error(`Conversations: ${response.status}`);
    return await response.json() as { conversations?: readonly ServedConversation[]; conversationId?: number | string };
  }, [base]);
  const reload = useCallback(async () => { const result = await call({}); setItems((result.conversations ?? []).map(item)); }, [call]);
  // Another endpoint (another owner's list) starts empty; switching conversations only reloads.
  useEffect(() => { setItems(undefined); }, [base]);
  useEffect(() => {
    if (base === undefined) return;
    let off = false;
    const load = () => call({}).then(result => { if (!off) setItems((result.conversations ?? []).map(item)); }).catch(() => {});
    void load();
    const timer = setInterval(load, pollMs);
    return () => { off = true; clearInterval(timer); };
  }, [call, pollMs, activeId]); // eslint-disable-line react-hooks/exhaustive-deps
  return useMemo(() => {
    if (!items) return undefined;
    const changed = async () => { await reload().catch(() => {}); await latest.current.onChange?.(); };
    const op = (name: string, body: unknown) => call({ op: name }, body);
    return {
      items, activeId, reload,
      onSelect: (id: string) => latest.current.onSelect(id),
      onNew: () => { void op('create', {}).then(async result => { await changed(); if (result.conversationId !== undefined) latest.current.onSelect(String(result.conversationId)); }).catch(() => {}); },
      search: async (query: string, { archived }: { readonly archived: boolean }, signal: AbortSignal) =>
        ((await call({ ...(query ? { q: query } : {}), ...(archived ? { archived: '1' } : {}) }, undefined, signal)).conversations ?? []).map(item),
      rename: async (id: string, title: string) => { await op('rename', { conversationId: id, title }); await changed(); },
      archive: async (id: string, archived: boolean) => { await op('archive', { conversationId: id, archived }); await changed(); },
      remove: async (id: string) => { await op('delete', { conversationId: id }); await changed(); },
      fork: async (at: string) => {
        const from = latest.current.activeId;
        if (from === undefined) return;
        const { conversationId } = await op('fork', { conversationId: from, at });
        await changed();
        if (conversationId !== undefined) latest.current.onSelect(String(conversationId));
      },
    };
  }, [items, activeId, call, reload]);
}

import { useEffect, useLayoutEffect, useMemo, useState } from 'react';
import { createNativeChatController } from '@hachej/boring-ui-kit/native-chat';
import type { ChatIdentity, NativeChatController } from '@hachej/boring-ui-kit/native-chat';
import { createRemoteChat } from '@hachej/boring-ui-kit/remote-chat';
import type { RemoteChat } from '@hachej/boring-ui-kit/remote-chat';
import type { PiChatActions } from '../pi-chat/pi-chat';

export type RemoteChatState =
  | { readonly status: 'connecting'; readonly conversationId: string | undefined }
  | { readonly status: 'offline'; readonly conversationId: string | undefined; readonly error: string }
  | { readonly status: 'ready'; readonly conversationId: string; readonly controller: NativeChatController; readonly actions: PiChatActions; readonly configure: RemoteChat['configure'] };

/**
 * One native chat controller per selected conversation over the host's chat transport (`createChatTransportHandler` of
 * `@hachej/boring-agent/chat-transport`). `endpoint(id)` names the transport URL of a conversation; `fetch` is the host's authenticated fetch.
 * The remote chat reopens a dropped stream itself (the controller reads `reconnecting` meanwhile); it never means the task stopped.
 * A failed connect retries every second. The previous conversation's controller is never handed out: it is disposed on change.
 */
export function useRemoteChat({ conversationId, endpoint, fetch, identity }: {
  readonly conversationId: string | undefined;
  readonly endpoint: (conversationId: string) => string | URL;
  readonly fetch: (request: Request) => Promise<Response>;
  readonly identity: ChatIdentity | undefined;
}): RemoteChatState {
  const url = conversationId === undefined ? undefined : String(endpoint(conversationId));
  const key = JSON.stringify([conversationId, url, identity?.runtimeId, identity?.scopeId, identity?.principalId]);
  const binding = useMemo(() => ({ key, fetch }), [key]); // eslint-disable-line react-hooks/exhaustive-deps
  useLayoutEffect(() => { binding.fetch = fetch; }, [binding, fetch]);
  const [stored, setStored] = useState<{ readonly binding: typeof binding; readonly chat: RemoteChatState }>();
  useEffect(() => {
    if (conversationId === undefined || !identity || url === undefined) return;
    const setChat = (chat: RemoteChatState) => setStored({ binding, chat });
    let disposed = false, controller: NativeChatController | undefined, remote: RemoteChat | undefined;
    setChat({ status: 'connecting', conversationId });
    void (async () => {
      while (!disposed) {
        try {
          remote = await createRemoteChat({ endpoint: url, fetch: request => binding.fetch(request) });
          if (disposed) return void remote.close();
          controller = createNativeChatController({ identity, ...remote });
          await controller.connect();
          if (disposed) return void controller.dispose();
          // Human-in-the-loop answers and queue withdrawal are optional on the transport: pass only what it offers.
          const actions: { answer?: RemoteChat['answer']; withdraw?: RemoteChat['withdraw'] } = {};
          if (typeof remote.answer === 'function') actions.answer = remote.answer;
          if (typeof remote.withdraw === 'function') actions.withdraw = remote.withdraw;
          setChat({ status: 'ready', controller, conversationId, actions, configure: remote.configure });
          return;
        } catch (error) {
          controller?.dispose(); controller = undefined; void remote?.close(); remote = undefined;
          if (disposed) return;
          setChat({ status: 'offline', conversationId, error: String((error as Error)?.message ?? error) });
          await new Promise(resolve => setTimeout(resolve, 1000));
        }
      }
    })();
    return () => { disposed = true; controller?.dispose(); void remote?.close(); };
  }, [binding]); // eslint-disable-line react-hooks/exhaustive-deps
  return identity && stored?.binding === binding ? stored.chat : { status: 'connecting', conversationId };
}

/*
